'use strict';
const shell=document.querySelector('.app'),demo=new URLSearchParams(location.search).get('preview')==='1';
const startup=document.createElement('section');startup.className='startup';startup.setAttribute('aria-label','Hexapod connection');
startup.innerHTML=`<div class="boot-brand"><span>⬡</span> HEXAPOD <small>NEURAL INTERFACE / 01</small></div><div class="boot-top-right">${demo?'ANIMATION PREVIEW':'LOCAL LINK / ESP32'}</div><div class="holo-stage"><div class="holo-reticle"></div><div class="holo-sweep"></div><canvas id="hologram" aria-label="Rotating isometric hexapod hologram" role="img"></canvas><span class="hud-label left">P3DRO<br><b>18 AXES / 6 LIMBS</b></span><span class="hud-label right">KINEMATIC ARRAY<br><b>STANDBY</b></span><div class="lock-flash"></div></div><div class="boot-copy"><div class="link-state" role="status"><span class="link-spinner"></span><span id="link-status">AWAITING CONNECTION</span></div><button id="connect-robot" class="primary">Connect to hexapod <span>→</span></button><p id="connection-error" hidden role="alert"></p><a id="local-controller" href="http://192.168.4.1/" hidden>Open ESP32-hosted app ↗</a></div><div class="boot-bottom"><span>HEXAPOD / CONTROL SYSTEM</span><span>${demo?'PREVIEW · NO ROBOT CONNECTION':'LOCAL COMMAND INTERFACE'}</span></div>`;
document.body.appendChild(startup);shell.inert=true;shell.setAttribute('aria-hidden','true');
let bootState='waiting',bootAbort=null,bootTimers=[],bootGeneration=0;
const lowMotion=matchMedia('(prefers-reduced-motion: reduce)').matches;
const setBootStatus=s=>$('link-status').textContent=s;
function later(fn,ms){bootTimers.push(setTimeout(fn,lowMotion?Math.min(ms,80):ms));}
function resetStartup(message='AWAITING CONNECTION'){bootGeneration++;bootAbort?.abort();bootTimers.forEach(clearTimeout);bootTimers=[];bootState='waiting';startup.hidden=false;startup.classList.remove('connecting','linked','departing','connection-failed');document.body.classList.add('booting');document.body.classList.remove('deck-ready');shell.inert=true;shell.setAttribute('aria-hidden','true');$('connect-robot').disabled=false;$('connect-robot').innerHTML='Connect to hexapod <span>→</span>';$('connection-error').hidden=true;$('local-controller').hidden=true;setBootStatus(message);}
function connectionError(message,offerLocal=false){bootState='waiting';startup.classList.remove('connecting');startup.classList.add('connection-failed');$('connection-error').textContent=message;$('connection-error').hidden=false;$('local-controller').hidden=!offerLocal;$('connect-robot').disabled=false;$('connect-robot').innerHTML='Retry connection <span>↻</span>';setBootStatus('LINK UNAVAILABLE');}
function validController(s){return s?.transport==='esp32'&&typeof s.enabled==='boolean'&&typeof s.hardwareOutput==='boolean'&&Array.isArray(s.legs)&&s.legs.length===6&&s.legs.every(l=>Array.isArray(l.links)&&l.links.length===4&&l.links.every(p=>Array.isArray(p)&&p.length===3&&p.every(Number.isFinite)));}
async function connectRobot(){
 if(bootState!=='waiting')return;bootState='connecting';const generation=++bootGeneration;startup.classList.remove('connection-failed');startup.classList.add('connecting');$('connection-error').hidden=true;$('local-controller').hidden=true;$('connect-robot').disabled=true;setBootStatus(demo?'PREVIEWING LINK SEQUENCE':'ESTABLISHING LOCAL LINK');$('connect-robot').textContent='Connecting…';
 if(demo){later(()=>{if(generation===bootGeneration)linkEstablished(null);},950);return;}
 const abort=new AbortController();bootAbort=abort;const timeout=setTimeout(()=>abort.abort(),3500);
 try{const response=await fetch('/api/state',{cache:'no-store',signal:abort.signal});if(!response.ok)throw Error();const state=await response.json();if(!validController(state)||state.hardwareOutput!==false)throw Error();if(generation===bootGeneration)linkEstablished(state);}
 catch(error){if(generation===bootGeneration)connectionError(error.name==='AbortError'?'The ESP32 did not respond. Check its power and try again.':'No compatible HEXAPOD controller at this address.');}finally{clearTimeout(timeout);}
}
function linkEstablished(state){bootState='linked';startup.classList.remove('connecting');startup.classList.add('linked');setBootStatus(state?'ESP32 LINK VERIFIED':'PREVIEW LINK COMPLETE');$('connect-robot').innerHTML='Initializing control center <span>✓</span>';if(state&&!state.usb)window.hexapodLink?.attach(state);else if(!state)stop('Animation preview. No ESP32 connected.');later(()=>{startup.classList.add('departing');document.body.classList.remove('booting');document.body.classList.add('deck-ready');shell.inert=false;shell.removeAttribute('aria-hidden');},800);later(()=>{startup.hidden=true;bootState='control';$('enable').focus({preventScroll:true});},1900);}
$('connect-robot').onclick=connectRobot;
const back=document.createElement('button');back.id='show-startup';back.className='quiet';back.textContent='⌁ Connection';back.setAttribute('aria-label','Open robot connection screen');document.querySelector('header').insertBefore(back,$('stop'));
back.onclick=()=>{window.hexapodLink?.detach();stop('Control paused.');resetStartup();$('connect-robot').focus({preventScroll:true});};
document.addEventListener('visibilitychange',()=>{if(document.hidden&&['connecting','linked'].includes(bootState)){window.hexapodLink?.detach();resetStartup('CONNECTION PAUSED');}});
window.addEventListener('hexapod-link-lost',()=>{resetStartup('LINK LOST');connectionError('The robot stopped responding. Reconnect to continue.');});
